  ('slush', 'bùn loãng; tuyết tan; mỡ thừa, mỡ bỏ đi (ở tàu thuỷ)', 'danh từ ((cũng) slosh)', '/slʌʃ/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/slu/slush/slush__us_1.mp3'),
  ('pun', 'sự chơi chữ* nội động từ; chơi chữ* ngoại động từ; nện, đầm (đất)', 'danh từ', '/pʌn/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pun/pun__/pun__us_1.mp3'),
  ('lamp', 'đèn; mặt trời, mặt trăng, sao; nguồn ánh sáng (tinh thần...), nguồn hy vọng', 'danh từ', '/læmp/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lam/lamp_/lamp__us_1.mp3'),
  ('lump', 'cục, tảng, miếng; cái bướu, chỗ sưng u lên, chỗ u lồi lên; cả mớ, toàn bộ, toàn thể', 'danh từ', '/lʌmp/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lum/lump_/lump__us_1.mp3'),
  ('damp', 'sự ẩm ướt; không khí ẩm thấp; khi mỏ; (nghĩa bóng) sự nản chí, sự ngã lòng, sự nản lòng, sự chán nản', 'danh từ', '/dæmp/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dam/damp_/damp__us_1.mp3'),
  ('dump', 'vật ngắn bè bè, người lùn bè bè; thẻ chì (dùng trong một số trò chơi); đông đum (tiền Uc xưa)', 'danh từ', '/dʌmp/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dum/dump_/dump__us_1.mp3'),
  ('stamp', 'tem; con dấu; dấu; nhãn hiệu, dấu bảo đảm', 'danh từ', '/stæmp/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stamp/stamp__us_1.mp3'),
  ('stump', 'gốc cây (còn lại sau khi đốn); chân răng; mẩu chân cụt, mẩu tay cụt', 'danh từ', '/stʌmp/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/stu/stump/stump__us_1.mp3'),
  ('ton', 'tấn; ton (đơn vị dung tích tàu bè bằng 2, 831 m3); ton (đơn vị trọng tải của tàu bè bằng 1, 12 m3)', 'danh từ', '/tʌn/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ton/ton__/ton__us_1.mp3'),
