  ('suck', 'sự mút, sự bú, sự hút; ngụm, hớp (rượu); (số nhiều)(ngôn ngữ nhà trường), (từ lóng) kẹo', 'danh từ', '/sʌk/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suc/suck_/suck__us_1.mp3'),
