  ('peg', 'cái chốt, cái ngạc; cái móc, cái mắc (áo, mũ); cái cọc (căng dây lều)', 'danh từ', '/peɡ/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/peg/peg__/peg__us_1.mp3'),
