  ('hack', 'búa, rìu; cuốc chim (của công nhân mỏ); vết toác; vết thương do bị đá vào ống chân (đá bóng)* ngoại động từ', 'danh từ', '/hæk/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hac/hack_/hack__us_1.mp3'),
  ('hag', 'mụ phù thuỷ; mụ già xấu như quỷ; (động vật học) cá mút đá myxin ((cũng) hagfish)* danh từ', 'danh từ', '/hæɡ/', 'oxford+dict', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hag/hag__/hag__us_1.mp3'),
